"explanation": "実用新案法第15条により、実用新案権の存続期間は実用新案登録出願の日から起算して10年をもって終了する。起算点は出願日であり、期間は10年である。\n\nB：期間（10年）は正しいが起算点が誤り。設定登録日ではなく出願日が起点。\nC：起算点は正しいが期間が20年ではなく10年。20年は特許権の期間。\nD：起算点・期間とも誤り。\n\n【混同注意】特許権=出願日から20年、実用新案権=出願日から10年。両者の期間を取り違える誤答が頻出。\n【頻出】存続期間の起算点が「出願日」であること（特許・実案・意匠）と、商標だけが「登録日」起算である整理が有効。"

