"explanation": "出願の変更は、技術的な創作を保護する特許・実用新案・意匠の各出願相互間で認められる（特許法第46条、実用新案法第10条、意匠法第13条等）。商標は商品・役務の標識を保護する別系統の権利であり、特許出願を商標登録出願に変更することはできない。したがってDが誤り。\n\nA：正しい。実用新案登録出願を特許出願に変更できる。\nB：正しい。特許出願を実用新案登録出願に変更できる。\nC：正しい。変更後は元の出願は取り下げたものとみなされる。\n\n【混同注意】特許・実用新案・意匠（創作の保護）は相互変更可だが、商標（標識の保護）は変更の輪に入らない。\n【頻出】変更出願にも出願日の遡及効がある点が問われやすい。"

