"explanation": "特許法第70条第1項により、特許発明の技術的範囲は特許請求の範囲の記載に基づいて定められる。明細書や図面はその解釈の参酌資料となる（同条第2項）。\n\nA：要約書の記載は技術的範囲の解釈に用いてはならない（同条第3項）。\nC：技術的範囲は出願時に確定する書類によって画されるものであり、後日作成した説明書で変動するものではない。\nD：権利者の主観的意図で範囲が決まるのではなく、客観的に特許請求の範囲の記載を基準として判断される。\n\n【頻出】「技術的範囲は特許請求の範囲が基準・要約書は不可」が頻出。\n【混同注意】明細書・図面は参酌できるが、要約書は参酌対象から明文で除外されている点に注意。"

