"explanation": "商標法第8条第1項（先願主義）により、同一・類似の商標について異なった日に二以上の出願があったときは、最先の商標登録出願人のみが登録を受けることができる。\n\nB：先願主義により出願の前後で決まり、登録料納付の先後で決まるのではない。\nC：同日出願のときは出願人間の協議によって定めるのが原則であり、協議不成立の場合に特許庁長官が行うくじにより定める（同条第2項・第5項）。Cは協議の段階を飛ばしている点で不正確。\nD：協議が成立しないときの最終的な決定はくじによるため、双方とも登録を受けられるわけではない。\n\n【頻出】「異日出願は先願者・同日出願は協議→不成立ならくじ」が頻出。\n【混同注意】特許の同日出願は『協議不成立ならいずれも不可』だが、商標の同日出願は『協議不成立ならくじで決定』という結論の違いに注意。"

