"explanation": "商標法第20条により、更新登録の申請は商標権の存続期間の満了前の一定期間内（原則として満了前6月から満了日まで）にすることができる。所定の更新登録料を納付して申請する。\n\nB：更新登録の申請にあたり登録商標の使用を立証する必要はない（不使用は別途不使用取消審判で争われる）。\nC：更新は何度でも繰り返すことができ、回数の制限はない。\nD：更新申請は存続期間の満了前の一定期間内にするものであり、設定登録日にするものではない。\n\n【頻出】「更新により半永久的に存続でき、使用の立証は不要」が頻出。\n【混同注意】更新時に使用の立証は不要だが、3年以上不使用の場合は不使用取消審判で取り消され得る点と区別する。"

