"explanation": "他人の小説を翻案して脚本を作成する行為は翻案権（著作権法第27条）に、これを公衆向けに上演する行為は上演権（第22条）および二次的著作物の利用に関する原著作者の権利（第28条）に関わるため、原則として著作権者の許諾が必要となる。\n\nB：引用の要件（第32条）を満たす掲載は権利制限規定により許諾不要。\nC：個人的に読むためのコピーは私的使用のための複製（第30条）に該当し許諾不要。\nD：非営利・無料・無報酬の演奏（第38条）は権利制限規定により許諾不要。\n\n【頻出】権利制限規定に該当しない利用（翻案・公衆向け上演等）には許諾が必要となる点が頻出。\n【混同注意】私的複製・引用・非営利無償上演はいずれも権利制限規定であり許諾不要だが、翻案＋公衆向け利用は許諾が必要となる。"

