"answer": 2,

"explanation": "正しいのはアとイであり、組み合わせはCが正解。\n\nア：正しい。著作隣接権は実演家・レコード製作者・放送事業者・有線放送事業者に認められる（著作権法第89条）。\nイ：正しい。著作権の移転は登録しなければ第三者に対抗できない（第77条）。\nウ：誤り。著作者人格権は財産権ではなく一身専属の人格権であり譲渡できない（第59条）。\nエ：誤り。非営利・無料・無報酬の3要件はすべて満たす必要があり、一つでも欠ければ許諾が必要（第38条）。\n\n【頻出】著作隣接権・登録の対抗要件・人格権の一身専属性・非営利上演の3要件を横断的に問う複合問題。\n【混同注意】人格権は譲渡不可、非営利上演は3要件すべて必要という2点が引っかけの中心。"

