"explanation": "不正競争防止法第2条第1項第1号により、他人の周知な商品等表示と同一・類似のものを使用し、他人の商品・営業と混同を生じさせる行為は不正競争に該当する。\n\nB：技術的思想の無断実施は特許権侵害の問題であり、不正競争防止法の規制内容とは異なる。\nC：登録商標の使用に関する規制は商標法の領域であり、不正競争防止法は登録の有無を問わず周知・著名表示等を保護する。\nD：著作物の無断複製は著作権法の領域。\n\n【頻出】不正競争の類型（周知表示混同惹起・著名表示冒用・形態模倣・営業秘密侵害等）の理解が頻出。\n【混同注意】不正競争防止法は登録を要さず周知性・著名性等の事実状態を保護する点が、登録主義の商標法と対比される。"

