"explanation": "不正競争防止法第2条第1項第3号により、他人の商品の形態を模倣した商品を譲渡・貸渡し・輸出入等する行為は不正競争に該当する。意匠登録がなくても一定期間、商品形態の模倣を規制できる。\n\nB：商品形態の模倣規制は登録を要しない。登録がなくても保護される点に意義がある。\nC：同種の商品が通常有する形態（商品の機能を確保するために不可欠な形態）は保護対象から除外される（同号括弧書）。\nD：保護期間は日本国内で最初に販売された日から起算して3年間である（同法第19条第1項第5号イ）。\n\n【頻出】「形態模倣規制＝登録不要・最初の販売から3年間」が頻出。\n【混同注意】機能上不可欠な形態は除外される点と、保護期間が3年である点が重要。意匠権（出願日から25年）との違いに注意。"

