"explanation": "ライセンス契約における実施料（ロイヤルティ）の算定方式には、契約時等に一定額を支払う固定額（一時金）方式、実施数量・売上高等に応じて支払うランニングロイヤルティ方式、両者を組み合わせる方式等がある。\n\nB：ライセンス契約は実施を許諾するものであり、特許権そのものが移転するわけではない（移転は譲渡）。\nC：実施許諾は通常実施権の許諾によることもでき、専用実施権の設定に限られない。\nD：許諾の範囲（地域・期間・分野・数量等）を限定することは可能であり、禁止されていない。\n\n【頻出】実施料の算定方式と、ライセンス（実施許諾）と譲渡（権利移転）の区別が頻出。\n【混同注意】ライセンスは権利を留保したまま実施を許諾するものであり、譲渡（権利移転）とは異なる点を押さえる。"

