"explanation": "秘密保持契約（NDA）は、取引・共同開発等に際して開示する秘密情報について、受領者が定められた目的以外に使用せず、第三者に開示・漏えいしないことを約する契約である。\n\nB：NDAの締結だけで情報が当然に営業秘密として法的保護を受けるわけではなく、別途、秘密管理性等の要件を満たす必要がある（ただしNDAは秘密管理性を裏付ける一要素となる）。\nC：NDAは技術提携に限らず、業務委託・取引交渉・M&A等の様々な場面で締結される。\nD：NDAではむしろ保護対象となる秘密情報の範囲を明確に特定することが重要であり、禁止されていない。\n\n【頻出】「NDA＝目的外使用の禁止・第三者開示の禁止・秘密情報の特定」が頻出。\n【混同注意】NDAの締結は営業秘密の秘密管理性を裏付ける一要素となり得るが、それだけで営業秘密としての保護が完成するわけではない点に注意。"

