"explanation": "正しいのはアとイであり、組み合わせはBが正解。\n\nア：正しい。特許権の移転（一般承継を除く）は登録が効力発生要件（特許法第98条）。\nイ：正しい。独占的ライセンスはライセンサーが他者へ重ねて許諾しないことを約するもの。\nウ：誤り。秘密保持契約の締結だけでは情報が当然に営業秘密として完全に保護されるわけではなく、別途、秘密管理性等の要件を満たす必要がある。\nエ：誤り。共同発明に係る権利は発明への現実の貢献に基づき共有となるのが原則であり、資金負担の多寡で当然に単独帰属するわけではない。\n\n【頻出】特許権移転の登録要件・独占的ライセンス・NDA・共同発明の権利帰属を横断的に問う複合問題。\n【混同注意】NDAだけでは営業秘密保護は完成しない（ウ）点と、権利帰属は貢献に基づく（エ）点が引っかけの中心。"

