"explanation": "特許法第35条第4項により、従業者等は職務発明について使用者等に特許を受ける権利を取得させた場合等には、相当の金銭その他の経済上の利益（相当の利益）を受ける権利を有する。\n\nB：従業者は相当の利益を受ける権利を有するため、誤り。\nC：相当の利益は金銭に限られず、留学の機会の付与やストックオプション等、金銭以外の経済上の利益も含まれる（2015年改正）。\nD：相当の利益の内容を定める手続は、協議・基準の開示・意見聴取等の状況を考慮して不合理でないことが求められ、一方的決定で正当性が問われないわけではない。\n\n【頻出】2015年改正による「相当の対価→相当の利益」への変更と、金銭以外の利益も認められる点が頻出。\n【混同注意】相当の利益の決定手続が不合理でないことが求められ、手続の適正さが問われる点を押さえる。"

