"question": "知的財産に関する次のア〜エの記述のうち、正しいものの組み合わせはどれか。\n\nア：著作権は無方式主義により創作と同時に発生する\nイ：知的財産権は属地主義により各国ごとに権利を取得する必要がある\nウ：実用新案権は実体審査を経て登録される\nエ：商標権の存続期間は登録日から25年である",

